arguments.command:
python3 -c "
import zipfile
from xml.etree import ElementTree as ET

HWPML_NS='http://www.hancom.co.kr/hwpml/2010/HWPML'

def localname(tag):
    return tag.split('}',1)[1] if tag.startswith('{') else tag

with zipfile.ZipFile('/root/clinic_intake_ready.hwpx') as z:
    for name in z.namelist():
        if not name.endswith('.xml'):
            continue
        xml = z.read(name).decode('utf-8')
        root = ET.fromstring(xml.encode('utf-8'))
        bad = []
        for p in root.findall(f'.//{{{HWPML_NS}}}p'):
            for el in p.iter():
                ln = localname(el.tag).lower()
                if ln in ('linesegarray','lineseg'):
                    bad.append((p.get('id'), localname(el.tag)))
        if bad:
            print(name, 'HAS LAYOUT CACHE:', bad)
        else:
            print(name, 'OK: no linesegarray/lineseg under paragraphs')
"

